"""Set the Xcode 26 location for the companion app generated by XcodeGen."""
from pathlib import Path
import re

project = Path("ReviewDock.xcodeproj/project.pbxproj")
contents = project.read_text(encoding="utf-8")

def update_watch_phase(match):
    phase = match.group(0)
    if "Embed Watch Content" not in phase and "ReviewDockWatch.app" not in phase:
        return phase
    phase = re.sub(r'dstPath = [^\n]+;', 'dstPath = "";', phase)
    return re.sub(r'dstSubfolderSpec = 16;', 'dstSubfolderSpec = 13;', phase)

updated = re.sub(
    r'isa = PBXCopyFilesBuildPhase;[\s\S]*?\n\s*};',
    update_watch_phase,
    contents,
)
if updated != contents:
    project.write_text(updated, encoding="utf-8")
